add_action( 'woocommerce_review_order_before_submit', 'perfectpixel_product_terms_checkbox', 9 );
add_action( 'woocommerce_checkout_process', 'perfectpixel_product_terms_validate' );

function perfectpixel_product_terms_needed() {
	$ids = wp_parse_id_list( '{{terms_product_ids}}' );
	if ( ! $ids || ! WC()->cart ) {
		return false;
	}
	foreach ( WC()->cart->get_cart() as $item ) {
		if ( in_array( (int) $item['product_id'], $ids, true ) ) {
			return true;
		}
	}
	return false;
}

function perfectpixel_product_terms_checkbox() {
	if ( ! perfectpixel_product_terms_needed() ) {
		return;
	}
	$page_id = (int) '{{terms_page_id}}';
	$text    = esc_html( '{{terms_checkbox_text}}' );
	if ( $page_id ) {
		$text = '<a href="' . esc_url( get_permalink( $page_id ) ) . '" target="_blank" rel="noopener">' . $text . '</a>';
	}
	echo '<p class="form-row validate-required perfectpixel-product-terms"><label class="woocommerce-form__label woocommerce-form__label-for-checkbox checkbox">';
	echo '<input type="checkbox" class="woocommerce-form__input woocommerce-form__input-checkbox input-checkbox" name="perfectpixel_product_terms" value="1"> ';
	echo '<span>' . $text . '</span>&nbsp;<abbr class="required">*</abbr></label></p>'; // phpcs:ignore WordPress.Security.EscapeOutput -- Escaped above.
}

function perfectpixel_product_terms_validate() {
	if ( perfectpixel_product_terms_needed() && empty( $_POST['perfectpixel_product_terms'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification
		wc_add_notice( esc_html( '{{terms_error}}' ), 'error' );
	}
}
